use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OperationId,Generation};
use semio_framework_value::retained_clone::RetainedCloneGrant;
fn clock()->Option<u64>{Some(1)}
fn stock()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1<<20,maximum_copy_bytes:1<<24,maximum_capacity_bytes:1<<24,maximum_release_bytes:1<<24,maximum_depth:4096}}
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:32768,maximum_capacity_bytes:16777216,maximum_release_bytes:1048576,maximum_depth:4096}}
pub(crate) fn request(standard:u8)->PreparationRequest{let data=semio_framework_pack_json::parse(include_str!("🔣️.json"),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();let mut source=[0;1024];let name=data["identity"]["source"].as_str().unwrap().as_bytes();source[..name.len()].copy_from_slice(name);let value=&data["limits"];PreparationRequest{identity:PreparationIdentity{standard,instance:data["identity"]["instance"].as_u64().unwrap()as u32,operation:data["identity"]["operation"].as_str().unwrap().parse().unwrap(),generation:1,revision:[0x11;32],source,source_len:name.len()as u16},scope:PreparationScope::Product(17),limits:PreparationLimits{work:value["work"].as_u64().unwrap()as usize,source_bytes:value["sourceBytes"].as_u64().unwrap()as usize,scratch_bytes:value["scratchBytes"].as_u64().unwrap()as usize,result_bytes:value["resultBytes"].as_u64().unwrap()as usize,vertices:value["vertices"].as_u64().unwrap()as usize,triangles:value["triangles"].as_u64().unwrap()as usize,depth:value["depth"].as_u64().unwrap()as usize}}}
#[test]fn inline_frame_layout_and_request_match_neutral_contract(){assert_eq!(std::mem::size_of::<Frame>(),512);assert_eq!(std::mem::size_of::<IndexPage>(),2048);let request=request(4);assert!(request.identity.valid());assert_eq!(request.identity.operation,9007199254740993);assert_eq!(request.limits.depth,64);assert_eq!(request.limits.work,8_000_000);assert!(<GeometryPreparationCursor as semio_framework_value::RetireOwned>::controlled_retirement_supported());}
fn volume(mesh:&PreparedPrimitive<'_>)->f64{(0..mesh.triangle_count()).map(|triangle|{let point=|corner|{let index=mesh.index(triangle,corner).unwrap()as usize;[mesh.position(index,0).unwrap(),mesh.position(index,1).unwrap(),mesh.position(index,2).unwrap()]};let(a,b,c)=(point(0),point(1),point(2));(a[0]*(b[1]*c[2]-b[2]*c[1])+a[1]*(b[2]*c[0]-b[0]*c[2])+a[2]*(b[0]*c[1]-b[1]*c[0]))/6.}).sum()}
pub(crate) fn verify_graph<G:GeometryGraph>(graph:&G,standard:u8,source_bytes:usize,expected:f64){let request=request(standard);let mut caller=OriginalJobFixtureCaller::admit(OperationId(request.identity.operation),Generation(request.identity.generation),stock(),clock,u64::MAX,1<<20);let mut cursor=GeometryPreparationCursor::new(request).unwrap();let read=CapturedGeometryRead{identity:&request.identity,source_bytes,graph};let mut turns=0;while !matches!(cursor.progress().phase,PreparationPhase::Ready|PreparationPhase::Refused)&&turns<10000{let before=cursor.progress().work;caller.turn(grant(),|cx|{cursor.advance(&read,&mut PreparationTurn{identity:&request.identity,cx}).unwrap();Ok(())}).unwrap();assert_eq!(cursor.progress().work,before+1);turns+=1;}assert_eq!(cursor.progress().phase,PreparationPhase::Ready,"{:?}",cursor.progress());let mesh=cursor.prepared(&read,0).unwrap().unwrap();assert_eq!((mesh.product,mesh.representation),(17,11));assert!((volume(&mesh)-expected).abs()<1e-9);assert_eq!(mesh.vertex_count(),8);assert_eq!(mesh.triangle_count(),12);assert!(cursor.progress().result_bytes>336);cursor.begin_close();let before=cursor.progress();caller.turn(RetainedCloneGrant{maximum_release_bytes:0,..grant()},|cx|{cursor.close(&mut PreparationTurn{identity:&request.identity,cx}).unwrap();Ok(())}).unwrap();assert_eq!(cursor.progress().result_bytes,before.result_bytes);assert_eq!(cursor.progress().scratch_bytes,before.scratch_bytes);for _ in 0..1000{if cursor.terminal_is_empty(){break}caller.turn(grant(),|cx|{cx.with_original_retirement(|cx|{cursor.close(&mut PreparationTurn{identity:&request.identity,cx}).unwrap();Ok(())})}).unwrap();}assert!(cursor.terminal_is_empty());assert_eq!((cursor.progress().scratch_bytes,cursor.progress().result_bytes),(0,0));caller.retire(stock());}
